#!/bin/zsh
# Deploys site/ to the Cloudflare Pages project "ieum" (https://ieum.calmwork.today).
# - Copies the folder first without .omc: tool state written there by hooks would otherwise be published.
# - Stamps the page with the version and size of the latest GitHub release ({{VERSION}}, {{SIZE}}).
# - Writes latest.json, the update feed the app reads (version, download address, SHA-256, notes). Publishing it is what offers
#   a release to installed apps, so run this after the release exists.
# - The pages are generated by Scripts/build-site.py from site-src/index.template.html (one page per language, sitemap, llms files).
# Usage: Scripts/deploy-site.sh [--dry-run | --preview]
#   --dry-run  prints latest.json and deploys nothing
#   --preview  deploys to a Cloudflare Pages preview URL (branch "preview"); the live site and the update feed stay as they are
set -e
cd "$(dirname "$0")/.."
repo=stoneidev/ieum
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

tag=$(gh release view --repo $repo --json tagName -q .tagName)
version=${tag#v}
gh release download "$tag" --repo $repo --pattern Ieum.dmg --dir "$tmp/dl"
bytes=$(stat -f %z "$tmp/dl/Ieum.dmg")
sha=$(shasum -a 256 "$tmp/dl/Ieum.dmg" | awk '{print $1}')
size=$(python3 -c "print(f'{$bytes / 1e6:.1f} MB')")

python3 Scripts/build-site.py "$tmp/site"
find "$tmp/site" \( -name '*.html' -o -name 'llms*.txt' \) -exec sed -i '' "s/{{VERSION}}/$version/g; s/{{SIZE}}/$size/g" {} +
if grep -rq '{{' "$tmp/site" --include='*.html' --include='llms*.txt'; then echo "unreplaced placeholder in the built site" >&2; exit 1; fi

# Release notes: English bullets, then a line with --- , then the Korean bullets.
gh release view "$tag" --repo $repo --json body -q .body > "$tmp/body.md"
python3 -I - "$version" "$tag" "$bytes" "$sha" "$tmp/body.md" "$tmp/site/latest.json" <<'PY'
import json, sys
version, tag, size, sha, body_path, out = sys.argv[1:]
body = open(body_path, encoding="utf-8").read().replace("\r", "")
english, _, korean = body.partition("\n---")
bullets = lambda text: [line[2:].strip() for line in text.splitlines() if line.startswith("- ") and "notarized by Apple" not in line]
notes = {"en": bullets(english)}
if bullets(korean):
    notes["ko"] = bullets(korean)
# The update window of every app already installed (0.13.0 and earlier) has a fixed height of 372 points and room for about four lines
# of notes: more pushes its title and its buttons out of the window (it happened with 0.13.0). Installed apps cannot be fixed
# afterwards, so refuse here. A line holds about 52 English or 26 Korean characters.
import math
for language, items in notes.items():
    per_line = 52 if language == "en" else 26
    lines = sum(math.ceil(len(item) / per_line) for item in items)
    if len(items) > 4 or lines > 4:
        sys.exit(f"release notes ({language}) take {lines} lines in the update window, at most 4 fit: use up to 3 short bullets "
                 f"(about {per_line} characters each); shorten them with gh release edit")
feed = {
    "version": version,
    "url": f"https://github.com/stoneidev/ieum/releases/download/{tag}/Ieum.dmg",
    "sha256": sha,
    "size": int(size),
    "minimumMacOS": "14.0",
    "notes": notes,
}
json.dump(feed, open(out, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
PY
if [ "$1" = "--dry-run" ]; then echo "version $version ($size)"; cat "$tmp/site/latest.json"; exit 0; fi
if [ "$1" = "--preview" ]; then
  echo "deploying a preview of version $version ($size)"
  npx --yes wrangler pages deploy "$tmp/site" --project-name ieum --branch preview
  exit 0
fi
echo "deploying version $version ($size)"
npx --yes wrangler pages deploy "$tmp/site" --project-name ieum --branch main
